109	string load_file(string file_name) {
110		cout << "正在读取文法文件：" << file_name << endl;
111		ifstream in(file_name.c_str());
112		if (!in) {
113			cout << "文法文件打开失败，请检查文件是否存在：" << file_name << endl;
114			return "";
115		}
116		//把文件内容整体流入字符串缓冲区
117		stringstream buffer;
