	for (unsigned int i = 0; success && i < input.length(); i++) {
		if (find(table.col.begin(), table.col.end(), input[i]) == table.col.end()) {
			cout << "输入串中的“" << input[i] << "”不是该文法的终结符" << endl;
			success = false;
		}
	}

	//分析过程表头
	cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;

	//分析步数上限：文法中存在环时可以及时收手，不至于死循环
	const int MAX_STEP = 10000;
	int step = 0;
	while (success) {
		step++;
		if (step > MAX_STEP) {
			cout << "分析步数超过" << MAX_STEP << "步，分析终止" << endl;
			success = false;
			break;
		}
