			//分析栈只剩结束标志：输入串同时读完则分析成功，否则出错
			print_state(analysis_s, input_s, rule_temp);
			if (cur != '#') {
				cout << "分析栈已经归约完毕，输入串却还剩下“" << cur << "”，分析失败" << endl;
				success = false;
