}
//求出全部非终结符的Follow集，同样用迭代代替递归，任何文法都能在有限步内收敛
static void allFollow(const vector<rule>& rules, vector<char>& nts, vector<set<char> >& follows) {
	vector<set<char> > firsts;
	vector<char> first_nts;
	allFirst(rules, first_nts, firsts);
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (index_of(nts, rules[i].left) < 0) {
			nts.push_back(rules[i].left);
			follows.push_back(set<char>());
		}
	}
	//“#”是输入串的结束标志，任何非终结符的Follow集里都带上它
	for (unsigned int i = 0; i < follows.size(); i++) {
		follows[i].insert('#');
	}
	bool changed = true;
	while (changed) {
		changed = false;
		for (unsigned int i = 0; i < rules.size(); i++) {
			int left_at = index_of(nts, rules[i].left);
			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
				const string& part = rules[i].right[j];
				for (unsigned int k = 0; k < part.length(); k++) {
					int at = index_of(nts, part[k]);
					if (at < 0) {
						continue;//终结符没有Follow集
					}
					//紧跟其后的符号串的First集去掉“@”之后并入Follow集
					set<char> first = firstOfString(part.substr(k + 1), rules, first_nts, firsts);
					bool at_end = false;
					for (set<char>::iterator it = first.begin(); it != first.end(); it++) {
						if (*it == '@') {
							at_end = true;//后继符号串能推出空串，还要并入规则左部的Follow集
						}
						else if (follows[at].insert(*it).second) {
							changed = true;
						}
					}
					if (at_end && left_at >= 0) {
						insert_all(follows[at], follows[left_at], changed);
					}
				}
			}
		}
	}
}
F_set findFollow(const char non_terminal, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = false;
	f_set.left = non_terminal;
	//“#”是输入串的结束标志，任何非终结符的Follow集里都带上它
	f_set.right.insert('#');
	vector<char> nts;
	vector<set<char> > follows;
	allFollow(rules, nts, follows);
	int at = index_of(nts, non_terminal);
	if (at >= 0) {
		f_set.right.insert(follows[at].begin(), follows[at].end());
	}
	return f_set;
}
