void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;
	//标准输入被提前关闭（例如没有任何输入）时按空串处理，避免后面用到未初始化的内容
	if (!cin) {
		input = "";
	}

	//分析栈：栈底压入结束标志“#”，其上压入文法的开始符号，即分析表的第一行
	stack<char> analysis_s;
	analysis_s.push('#');
	if (!table.row.empty()) {
		analysis_s.push(table.row[0]);
	}
	//输入栈：结束标志“#”压在栈底，待分析的字符串倒序入栈，栈顶就是当前输入符号
	stack<char> input_s;
	input_s.push('#');
	for (int i = (int)input.length() - 1; i >= 0; i--) {
		input_s.push(input[i]);
	}

	//分析是否成功的标志，一旦出现无法匹配或者查不到产生式的情况就置为false
	bool success = true;
	if (table.row.empty() || table.col.empty()) {
		cout << "没有可用的文法规则，无法进行语法分析" << endl;
		success = false;
	}
	//输入串里出现了文法之外的符号时不必再分析，直接判定为不是该文法的句子
	for (unsigned int i = 0; success && i < input.length(); i++) {
		if (find_col(table, input[i]) < 0) {
			cout << "输入串中的“" << input[i] << "”不是该文法的终结符" << endl;
			success = false;
		}
	}

	//分析过程表头
	cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;

	//分析步数上限：文法中存在环时可以及时收手，不至于死循环
	const int MAX_STEP = 500 + 100 * (int)input.length();
	int step = 0;
	while (success) {
		step++;
		if (step > MAX_STEP) {
			cout << "分析步数超过上限" << MAX_STEP << "，分析终止" << endl;
			success = false;
			break;
		}
		if (analysis_s.empty() || input_s.empty()) {
			success = false;//两个栈的栈底都是“#”，正常情况下不会被取空
			break;
		}
		char top = analysis_s.top();
		char cur = input_s.top();
		//本步所用的产生式：左部为0且右部为空表示这一步既不是推导也不是匹配
		rule rule_temp;
		rule_temp.left = 0;
		if (top == '#') {
			//分析栈只剩结束标志：输入串同时读完则分析成功，否则出错
			print_state(analysis_s, input_s, rule_temp);
			if (cur != '#') {
				cout << "分析栈已经归约完毕，输入串却还剩下“" << cur << "”，分析失败" << endl;
				success = false;
			}
			break;
		}
		int r = find_row(table, top);
		if (r < 0) {
			//栈顶是终结符：与当前输入符号相同就一起弹出，否则匹配失败
			if (top != cur) {
				print_state(analysis_s, input_s, rule_temp);
				cout << "栈顶终结符“" << top << "”与输入符号“" << cur << "”不匹配，分析失败" << endl;
				success = false;
				break;
			}
			rule_temp.left = top;//左部是终结符、右部为空，表示这一步是匹配动作
			print_state(analysis_s, input_s, rule_temp);
			analysis_s.pop();
			input_s.pop();
			continue;
		}
		//栈顶是非终结符：查分析表决定用哪一条产生式去展开
		int c = find_col(table, cur);
		unsigned int at = 0;
		if (c >= 0) {
			at = (unsigned int)r * table.col.size() + (unsigned int)c;
		}
		if (c < 0 || at >= table.rules.size() || table.rules[at].right.empty()) {
			print_state(analysis_s, input_s, rule_temp);
			cout << "分析表中[" << top << "," << cur << "]处没有产生式，分析失败" << endl;
			success = false;
			break;
		}
		rule_temp = table.rules[at];
		print_state(analysis_s, input_s, rule_temp);
		//用产生式右部替换栈顶的非终结符：右部倒序入栈，最左边的符号正好留在栈顶
		analysis_s.pop();
		const string& right_part = rule_temp.right[0];
		for (int k = (int)right_part.length() - 1; k >= 0; k--) {
			if (right_part[k] == '@') {
				continue;//“@”代表空串，不必入栈
			}
			analysis_s.push(right_part[k]);
		}
	}

	cout << endl << "字符串" << input;
	if (!success) {
		cout << "不";
	}
	cout << "是该文法的句子" << endl;
}

//在非终结符表中查找某个符号的下标，找不到时返回-1
static int index_of(const vector<char>& table, const char c) {
	for (unsigned int i = 0; i < table.size(); i++) {
		if (table[i] == c) {
			return (int)i;
		}
	}
	return -1;
}
//往集合里添加元素，集合确实变大了就把changed置为true
static void insert_all(set<char>& to, const set<char>& from, bool& changed) {
	for (set<char>::const_iterator it = from.begin(); it != from.end(); it++) {
		if (to.insert(*it).second) {
			changed = true;
		}
	}
}
//已知各非终结符的First集时，求一个符号串的First集
static set<char> firstOfString(const string ss, const vector<char>& nts, const vector<set<char> >& firsts) {
	set<char> result;
	bool all_epsilon = true;//符号串中的每个符号都能推出空串时，First集里才有“@”
	for (unsigned int i = 0; i < ss.length(); i++) {
		char c = ss[i];
		if (c == '@') {
			continue;//“@”本身就代表空串，不影响它后面的符号
		}
		int at = index_of(nts, c);
		if (at < 0) {
			result.insert(c);//终结符直接进入First集
			all_epsilon = false;
			break;//终结符后面的符号对First集不再有贡献
		}
		//非终结符：把它的First集去掉“@”之后并进来
		for (set<char>::const_iterator it = firsts[at].begin(); it != firsts[at].end(); it++) {
			if (*it != '@') {
				result.insert(*it);
			}
		}
		if (firsts[at].count('@') == 0) {
			all_epsilon = false;
			break;//该非终结符推不出空串，后面的符号对First集不再有贡献
		}
	}
	if (all_epsilon) {
		result.insert('@');//整个符号串都能推出空串
	}
	return result;
}
//求出全部非终结符的First集：反复迭代直到所有集合都不再变化，
//这样左递归、相互递归的文法也只会迭代有限次，不会陷入无限递归
static void allFirst(const vector<rule>& rules, vector<char>& nts, vector<set<char> >& firsts) {
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (index_of(nts, rules[i].left) < 0) {
			nts.push_back(rules[i].left);
			firsts.push_back(set<char>());
		}
	}
	bool changed = true;
	while (changed) {
		changed = false;
		for (unsigned int i = 0; i < rules.size(); i++) {
			int at = index_of(nts, rules[i].left);
			if (at < 0) {
				continue;
			}
			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
				set<char> sub = firstOfString(rules[i].right[j], nts, firsts);
				insert_all(firsts[at], sub, changed);
			}
		}
	}
}
F_set findFirst(const string ss, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	vector<char> nts;
	vector<set<char> > firsts;
	allFirst(rules, nts, firsts);
	f_set.right = firstOfString(ss, nts, firsts);
	return f_set;
}
vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules) {
	//逐个求出各条规则右部符号串的First集，重复的右部在set里已经合并，只会显示一次
	vector<F_set> f_sets;
	cout << "各规则右部的First集：" << endl;
	for (set<string>::iterator it = right_parts.begin(); it != right_parts.end(); it++) {
		F_set f_set = findFirst(*it, rules);
		cout << "    " << f_set << endl;
		f_sets.push_back(f_set);
	}
	cout << endl;
	return f_sets;
}

//求出全部非终结符的Follow集，同样用迭代代替递归，任何文法都能在有限步内收敛
static void allFollow(const vector<rule>& rules, vector<char>& nts, vector<set<char> >& follows) {
	vector<set<char> > firsts;
	vector<char> first_nts;
	allFirst(rules, first_nts, firsts);
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (index_of(nts, rules[i].left) < 0) {
			nts.push_back(rules[i].left);
			follows.push_back(set<char>());
		}
	}
	//“#”是输入串的结束标志，任何非终结符的Follow集里都带上它
	for (unsigned int i = 0; i < follows.size(); i++) {
		follows[i].insert('#');
	}
	bool changed = true;
	while (changed) {
		changed = false;
		for (unsigned int i = 0; i < rules.size(); i++) {
			int left_at = index_of(nts, rules[i].left);
			for (unsigned int j = 0; j < rules[i].right.size(); j++) {
				const string& part = rules[i].right[j];
				for (unsigned int k = 0; k < part.length(); k++) {
					int at = index_of(nts, part[k]);
					if (at < 0) {
						continue;//终结符没有Follow集
					}
					//紧跟其后的符号串的First集去掉“@”之后并入Follow集
					set<char> first = firstOfString(part.substr(k + 1), first_nts, firsts);
					bool at_end = false;
					for (set<char>::iterator it = first.begin(); it != first.end(); it++) {
						if (*it == '@') {
							at_end = true;//后继符号串能推出空串，还要并入规则左部的Follow集
						}
						else if (follows[at].insert(*it).second) {
							changed = true;
						}
					}
					if (at_end && left_at >= 0) {
						insert_all(follows[at], follows[left_at], changed);
					}
				}
			}
		}
	}
}
F_set findFollow(const char non_terminal, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = false;
	f_set.left = non_terminal;
	//“#”是输入串的结束标志，任何非终结符的Follow集里都带上它
	f_set.right.insert('#');
	vector<char> nts;
	vector<set<char> > follows;
	allFollow(rules, nts, follows);
	int at = index_of(nts, non_terminal);
	if (at >= 0) {
		f_set.right.insert(follows[at].begin(), follows[at].end());
	}
	return f_set;
}
vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules) {
	//逐个求出各个非终结符的Follow集
	vector<F_set> f_sets;
	cout << "各非终结符的Follow集：" << endl;
	for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
		F_set f_set = findFollow(*it, rules);
		cout << "    " << f_set << endl;
		f_sets.push_back(f_set);
	}
	cout << endl;
	return f_sets;
}
=====PRINT_STATE=====
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
	//分析栈按“栈底到栈顶”的顺序输出，栈底的“#”排在最左边
	string analysis = "";
	while (!analysis_s.empty()) {
		analysis = string(1, analysis_s.top()) + analysis;
		analysis_s.pop();
	}
	//输入栈按“栈顶到栈底”的顺序输出，正好是剩余的输入串
	string input = "";
	while (!input_s.empty()) {
		input += input_s.top();
		input_s.pop();
	}
	//所用产生式：右部为空说明这一步不是推导而是终结符匹配
	ostringstream action;
	if (!rule_temp.right.empty()) {
		action << rule_temp;
	}
	else if (rule_temp.left != 0) {
		action << "“" << rule_temp.left << "”匹配";
	}
	cout << setw(20) << analysis << setw(20) << input << setw(20) << action.str() << endl;
}

