### 7 · `parser_ll1_header` — first half of `LL_1` (+ lookup helpers)

```cpp
//在分析表的行表头里查找一个非终结符，找不到时返回-1
static int find_row(const LL_1_table& table, const char c) {
	for (unsigned int i = 0; i < table.row.size(); i++) {
		if (table.row[i] == c) {
			return (int)i;
		}
	}
	return -1;
}
//在分析表的列表头里查找一个终结符，找不到时返回-1
static int find_col(const LL_1_table& table, const char c) {
	for (unsigned int j = 0; j < table.col.size(); j++) {
		if (table.col[j] == c) {
			return (int)j;
		}
	}
	return -1;
}

LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules) {
	LL_1_table table;
	//行表头：按规则书写的先后顺序排列非终结符，这样第一行对应的就是文法的开始符号
	for (unsigned int i = 0; i < rules.size(); i++) {
		if (find_row(table, rules[i].left) < 0) {
			table.row.push_back(rules[i].left);
		}
	}
	//只出现在右部、没有产生式的非终结符同样占一行，避免分析表缺行
	for (set<char>::iterator it = non_terminal.begin(); it != non_terminal.end(); it++) {
		if (find_row(table, *it) < 0) {
			table.row.push_back(*it);
		}
	}
	//列表头：全部终结符再加上输入串的结束标志“#”，“#”固定放在最后一列
	for (set<char>::iterator it = terminal.begin(); it != terminal.end(); it++) {
		if (*it != '#' && *it != '@') {
			table.col.push_back(*it);
		}
	}
	table.col.push_back('#');
	//文法为空时直接返回一张空表，后面的下标运算不必再做
	if (table.row.empty()) {
		return table;
	}
	//表中每个单元格先放一条空规则，右部为空就表示该单元格没有产生式
	rule blank;
	blank.left = 0;
	table.rules.assign(table.row.size() * table.col.size(), blank);
	/* …builder half follows… */
```

> **Change I recommend to the landed code.** The version in the tree does `terminal.insert('#');` before the loop. `terminal` is a **non-const reference to the caller's set** — that mutates `main`'s `terminal` set (and any future caller's). `main` happens not to reuse it, so nothing breaks today, but a second `LL_1` call or a unit test that re-prints `terminal` after building the table would see a phantom terminal. Filter with `*it != '#'` and `push_back('#')` instead, as above; `'@'` is filtered for the same reason (`split_into_rules` already excludes it, but the check costs nothing).

### 8 · `parser_ll1_builder` — second half of `LL_1`

```cpp
//把一条产生式填进[第r行,终结符c列]的单元格里，只有右部为空的单元格才可以填
static void fill_cell(LL_1_table& table, const int r, const char c, const rule cell) {
	int j = find_col(table, c);
	if (r < 0 || j < 0) {
		return;//该符号不在表头里，不占分析表的单元格
	}
	unsigned int at = (unsigned int)r * table.col.size() + (unsigned int)j;
	if (at >= table.rules.size()) {
		return;//下标越界，防御性判断
	}
	if (!table.rules[at].right.empty()) {
		//一个单元格里挤进了两条产生式，说明该文法不是LL(1)文法，保留先填入的那一条
		cout << "警告：单元格[" << cell.left << "," << c << "]出现产生式冲突，该文法不是LL(1)文法" << endl;
		return;
	}
	table.rules[at] = cell;
}
	/* …continues LL_1() … */
	//逐条候选式填表：候选式的First集里有哪个终结符，就把它填到对应的单元格里
	for (unsigned int i = 0; i < rules.size(); i++) {
		int r = find_row(table, rules[i].left);
		if (r < 0) {
			continue;
		}
		for (unsigned int j = 0; j < rules[i].right.size(); j++) {
			//单元格里存放的是“左部::=某一个候选式”这样一条单候选式规则
			rule cell;
			cell.left = rules[i].left;
			cell.right.push_back(rules[i].right[j]);

			F_set first = findFirst(rules[i].right[j], rules);
			set<char> heads = first.right;
			//候选式能推出空串时，改用左部的Follow集来决定填表的位置
			if (heads.count('@') > 0) {
				F_set follow = findFollow(rules[i].left, rules);
				heads.insert(follow.right.begin(), follow.right.end());
			}
			for (set<char>::iterator it = heads.begin(); it != heads.end(); it++) {
				if (*it == '@') {
					continue;//“@”自身不是终结符，不占分析表的列
				}
				fill_cell(table, r, *it, cell);
			}
		}
	}
	return table;
}
```

Design points:

* The cell stores the **candidate string, not `"@"`** — so a nullable-but-not-literally-epsilon production like `E::=AB` lands in the table as `E::=AB`, which is what the parser must push. (test2 relies on this: `[E,#] = E::=AB`.)
* `findFollow` is only computed for nullable candidates — no cost on grammars without `@`.
* **Conflict policy — the one genuinely arguable choice.** The landed code writes unconditionally (last-write-wins, silently). I recommend keep-first plus the warning above: it is deterministic, documents the grammar as non-LL(1) for the user, and never fires on the three shipped grammars (I verified — no warning appears for test1/test2/test3, so no golden output changes). Trade-off, stated honestly: on `S::=Sa|b`, keep-first parks the left-recursive production in `[S,b]` and the parse then loops until the step cap trips, whereas last-wins happens to pick `S::=b` and succeed. Reversing the grammar to `S::=b|Sa` flips which policy gets lucky, so neither is systematically safer — **the step cap in §12 is the actual guard**, not the policy.

