```cpp
ostream& operator << (ostream& out, LL_1_table table) {
	out << "LL(1)分析表如下：" << endl;
	if (table.row.empty() || table.col.empty()) {
		//文法为空时给出提示，避免只打印一个光秃秃的表头
		out << "    （分析表为空，请检查文法文件的书写格式）" << endl << endl;
		return out;
	}
	//列表头：第一列留给非终结符，其余各列依次对应一个终结符
	out << setw(8) << " ";
	for (unsigned int j = 0; j < table.col.size(); j++) {
		out << setw(12) << table.col[j];
	}
	out << endl;
	//逐行输出：行首是非终结符，其后是各个单元格里的产生式，空单元格留白
	for (unsigned int i = 0; i < table.row.size(); i++) {
		out << setw(8) << table.row[i];
		for (unsigned int j = 0; j < table.col.size(); j++) {
			ostringstream cell;
			unsigned int at = i * table.col.size() + j;
			if (at < table.rules.size() && !table.rules[at].right.empty()) {
				cell << table.rules[at];
			}
			out << setw(12) << cell.str();
		}
		out << endl;
	}
	out << endl;
	return out;
}
```

`at < table.rules.size()` matters: `main` prints the table before the parser runs, so a malformed table must degrade to blanks rather than read out of range. The `ostringstream` is required — `setw` applies to one insertion, so `out << setw(12) << rule` would only pad the first character. Actual output for test3:

