### 10 · `parser_parse_state` — `print_state`

```cpp
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp) {
	//分析栈按“栈底到栈顶”的顺序输出，栈底的“#”排在最左边
	string analysis = "";
	while (!analysis_s.empty()) {
		analysis = string(1, analysis_s.top()) + analysis;
		analysis_s.pop();
	}
	//输入栈按“栈顶到栈底”的顺序输出，正好是剩余的输入串
	string input = "";
	while (!input_s.empty()) {
		input += input_s.top();
		input_s.pop();
	}
	//所用产生式：右部为空说明这一步不是推导而是终结符匹配
	ostringstream action;
	if (!rule_temp.right.empty()) {
		action << rule_temp;
	}
	else if (rule_temp.left != 0) {
		action << "“" << rule_temp.left << "”匹配";
	}
	cout << setw(20) << analysis << setw(20) << input << setw(20) << action.str() << endl;
}
```

Both stacks are taken **by value** (per the fixed signature) — that is deliberate and load-bearing: the function drains them destructively and the caller's copies are untouched. The two loops run in opposite directions because the stacks are oriented oppositely (analysis stack: `#` at the bottom, current symbol on top; input stack: `#` at the bottom, current symbol on top → popping yields the remaining input in reading order).

### 11 · `parser_analysis_init` — bootstrap half of `syntacticAnalysis`

```cpp
void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;
	//标准输入被提前关闭（例如没有任何输入）时按空串处理，避免后面用到未初始化的内容
	if (!cin) {
		input = "";
	}

	//分析栈：栈底压入结束标志“#”，其上压入文法的开始符号，即分析表的第一行
	stack<char> analysis_s;
	analysis_s.push('#');
	if (!table.row.empty()) {
		analysis_s.push(table.row[0]);
	}
	//输入栈：结束标志“#”压在栈底，待分析的字符串倒序入栈，栈顶就是当前输入符号
	stack<char> input_s;
	input_s.push('#');
	for (int i = (int)input.length() - 1; i >= 0; i--) {
		input_s.push(input[i]);
	}

	//分析是否成功的标志，一旦出现无法匹配或者查不到产生式的情况就置为false
	bool success = true;
	if (table.row.empty() || table.col.empty()) {
		cout << "没有可用的文法规则，无法进行语法分析" << endl;
		success = false;
	}
	//输入串里出现了文法之外的符号时不必再分析，直接判定为不是该文法的句子
	for (unsigned int i = 0; success && i < input.length(); i++) {
		if (find_col(table, input[i]) < 0) {
			cout << "输入串中的“" << input[i] << "”不是该文法的终结符" << endl;
			success = false;
		}
	}

	//分析过程表头
	cout << endl << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;
```

Four defensive details: `!cin` covers stdin EOF (`./parser </dev/null`) — C++11 already clears the string on failure, this is belt-and-braces; the reverse push loop uses a **signed** `int` (an `unsigned` loop with `i >= 0` never terminates); `table.row[0]` is only touched behind `!empty()`; and the unknown-symbol pre-check turns garbage input into one clear line instead of a confusing trace. Verified: `azb` on test3 →

```
输入串中的“z”不是该文法的终结符
…
字符串azb不是该文法的句子
```

### 12 · `parser_analysis` — parse loop (the only piece still `/* TODO */`)

```cpp
	//分析步数上限：文法中存在环时可以及时收手，不至于死循环
	const int MAX_STEP = 500 + 100 * (int)input.length();
	int step = 0;
	while (success) {
		step++;
		if (step > MAX_STEP) {
			cout << "分析步数超过上限" << MAX_STEP << "，分析终止" << endl;
			success = false;
			break;
		}
		if (analysis_s.empty() || input_s.empty()) {
			success = false;//两个栈的栈底都是“#”，正常情况下不会被取空
			break;
		}
		char top = analysis_s.top();
		char cur = input_s.top();
		//本步所用的产生式：左部为0且右部为空表示这一步既不是推导也不是匹配
		rule rule_temp;
		rule_temp.left = 0;
		if (top == '#') {
			//分析栈只剩结束标志：输入串同时读完则分析成功，否则出错
			print_state(analysis_s, input_s, rule_temp);
			if (cur != '#') {
				cout << "分析栈已经归约完毕，输入串却还剩下“" << cur << "”，分析失败" << endl;
				success = false;
			}
			break;
		}
		int r = find_row(table, top);
		if (r < 0) {
			//栈顶是终结符：与当前输入符号相同就一起弹出，否则匹配失败
			if (top != cur) {
				print_state(analysis_s, input_s, rule_temp);
				cout << "栈顶终结符“" << top << "”与输入符号“" << cur << "”不匹配，分析失败" << endl;
				success = false;
				break;
			}
			rule_temp.left = top;//左部是终结符、右部为空，表示这一步是匹配动作
			print_state(analysis_s, input_s, rule_temp);
			analysis_s.pop();
			input_s.pop();
			continue;
		}
		//栈顶是非终结符：查分析表决定用哪一条产生式去展开
		int c = find_col(table, cur);
		unsigned int at = 0;
		if (c >= 0) {
			at = (unsigned int)r * table.col.size() + (unsigned int)c;
		}
		if (c < 0 || at >= table.rules.size() || table.rules[at].right.empty()) {
			print_state(analysis_s, input_s, rule_temp);
			cout << "分析表中[" << top << "," << cur << "]处没有产生式，分析失败" << endl;
			success = false;
			break;
		}
		rule_temp = table.rules[at];
		print_state(analysis_s, input_s, rule_temp);
		//用产生式右部替换栈顶的非终结符：右部倒序入栈，最左边的符号正好留在栈顶
		analysis_s.pop();
		const string& right_part = rule_temp.right[0];
		for (int k = (int)right_part.length() - 1; k >= 0; k--) {
			if (right_part[k] == '@') {
				continue;//“@”代表空串，不必入栈
			}
			analysis_s.push(right_part[k]);
		}
	}

	cout << endl << "字符串" << input;
	if (!success) {
		cout << "不";
	}
	cout << "是该文法的句子" << endl;
}
```

Key invariants: `print_state` is always called **before** the action, so the row shows the state the production was chosen in (textbook convention); `find_row(table, top) < 0` **is** the terminal test — the table's row header is the authoritative non-terminal list, so `syntacticAnalysis` needs nothing but the table; the RHS is pushed right-to-left so the leftmost symbol ends up on top; `'@'` is skipped char-by-char rather than only when the whole candidate is `"@"`, so a stray `a@b` cannot corrupt the stack. The cap is proportional (`500 + 100·|w|`) so long legitimate inputs are never truncated while a cyclic table still terminates with a bounded amount of output (measured: 600 trace lines for a 1-char input, then the message).

